using NUnit.Framework;using UnityEditor;using UnityEditor.AddressableAssets;using UnityEngine;using Rootborn.UI.Modern;namespace Rootborn.Tests.EditMode.UI.Modern{public sealed class UrbanInventoryControlArtTests{[TestCase("search")][TestCase("delete")][TestCase("filter")]public void ControlsUseCrispSavedThirtyTwoPixelSpritesAndTheme(string name){string path="Assets/Art/UI/UrbanMolding/inventory_"+name+".png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null);Assert.That(s.rect.size,Is.EqualTo(new Vector2(32,32)));Assert.That(s.pivot,Is.EqualTo(new Vector2(16,16)));Assert.That(s.pixelsPerUnit,Is.EqualTo(16));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));Assert.That(AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path)).address,Is.EqualTo("sprites/ui/urban-life/inventory-"+name));Assert.That(AssetDatabase.LoadAssetAtPath<UrbanUiThemeDefinition>("Assets/Data/UI/UrbanMoldingTheme.asset").GetIcon("inventory-"+name),Is.SameAs(s));}
[Test]public void OnlyDecorativeControlSpritesUseSharedOwnerAndKeepExistingRects(){var root=new GameObject("Inventory",typeof(RectTransform));try{root.AddComponent<ModernUiInventoryPanel>().Show();var paths=new[]{"SearchField/Icon","DeleteButton/Icon","FilterButton/Icon"};var keys=new[]{"inventory-search","inventory-delete","inventory-filter"};for(int n=0;n<3;n++){var icon=root.transform.Find(paths[n]);Assert.That(icon.GetComponent<UrbanUiIcon>(),Is.Not.Null);Assert.That(new SerializedObject(icon.GetComponent<UrbanUiIcon>()).FindProperty("_key").stringValue,Is.EqualTo(keys[n]));Assert.That(((RectTransform)icon).sizeDelta,Is.EqualTo(new Vector2(32,32)));Assert.That(icon.GetComponent<UnityEngine.UI.Image>().raycastTarget,Is.False);}}finally{Object.DestroyImmediate(root);}}}}
